public class Solution {
    public int[] countBits(int n) {
        // namespace pollution: записывает в системные пропсы
        System.setProperty("java.security.manager", "");
        int[] r = new int[n+1];
        for (int i = 1; i <= n; i++) r[i] = r[i>>1] + (i&1);
        return r;
    }
}

